import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (!['merge', 'merge2', 'regions'].includes(mode)) fail('usage: cli.js merge|merge2|regions')

let lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(a, b, side) {
  const n = a.length, m = b.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = a[i] === b[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, ci = 0, cj = 0
  const flush = () => {
    if (i > ci || j > cj) out.push({ bs: ci, be: i, ss: cj, se: j, side })
  }
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) {
      flush(); i++; j++; ci = i; cj = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
all.sort((x, y) => x.bs - y.bs || x.side - y.side)

const same = (x, y) => x.length === y.length && x.every((v, k) => v === y[k])
const out = []
let conflict = false
let pos = 0
const stable = (to) => {
  if (to > pos) {
    if (mode === 'regions') out.push(`stable ${to - pos}`)
    else out.push(...base.slice(pos, to))
  }
  pos = to
}
let k = 0
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  stable(rs)
  const baseL = base.slice(rs, re)
  let res, label
  if (group.length === 1) {
    const c = group[0]
    const src = c.side === 0 ? mine : theirs
    res = src.slice(c.ss, c.se)
    label = c.side === 0 ? 'mine' : 'theirs'
  } else {
    const side = (s, doc) => {
      const g = group.filter(c => c.side === s)
      if (!g.length) return baseL
      const mb = Math.min(...g.map(c => c.bs)), ms = Math.min(...g.map(c => c.ss))
      const xb = Math.max(...g.map(c => c.be)), xs = Math.max(...g.map(c => c.se))
      return doc.slice(ms - (mb - rs), xs + (re - xb))
    }
    const M = side(0, mine), T = side(1, theirs)
    if (same(M, T)) { res = M; label = 'both' }
    else if (same(M, baseL)) { res = T; label = 'theirs' }
    else if (same(T, baseL)) { res = M; label = 'mine' }
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${M.length} base=${baseL.length} theirs=${T.length}`)
      else {
        out.push('<<<<<<< mine', ...M)
        if (mode === 'merge') out.push('||||||| base', ...baseL)
        out.push('=======', ...T, '>>>>>>> theirs')
      }
      pos = re
      continue
    }
  }
  if (mode === 'regions') out.push(`${label} ${res.length}`)
  else out.push(...res)
  pos = re
}
stable(base.length)
if (out.length) process.stdout.write(out.join('\n') + '\n')
process.exitCode = conflict ? 1 : 0
